function EML_RESIDUAL_STACK(a,b,c,lo,hi,K):
  f(x)     := exp(a)*log(b*x+c)
  clamp(x) := min(hi, max(lo, x))      # 1-Lipschitz projection
  function STACK(x):
      for i in 1..K:
          x <- x + f(clamp(x))         # (1+rho)-Lipschitz block
      return x
  return STACK

function CERTIFIED_DEPTH_BOUNDS(rho, K):
  return { floor: 1 + K*rho,
           exact: (1+rho)^K,
           ceiling: exp(K*rho) }
